(function () {
/* ===== 1_core.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 1/4 Core
 * Host / Storage / Chuẩn hóa model / Vùng bảo vệ / Lựa chọn vùng tĩnh
 * Thiết kế đúc kết từ bài học thực chiến v5.7 + kinh nghiệm kỹ thuật từ Refract Boundary v1.1.1
 * ========================================================================== */

var VERSION = '6.5.0';
var TAG = '[AR6]';
var CFG_KEY = 'ar6.cfg';
var LOG_KEY = 'ar6.log';
var MAX_LOG = 40;

/* ---------------- Host ---------------- */

function resolveHostWindow() {
  var cands = [];
  try { if (window.top) cands.push(window.top); } catch (e) {}
  try { if (window.parent) cands.push(window.parent); } catch (e) {}
  cands.push(window);
  for (var i = 0; i < cands.length; i++) {
    var w = cands[i];
    try {
      if (w && w.document && w.document.body && w.document.documentElement) return w;
    } catch (e) {}
  }
  return window;
}

/* Window nơi script tự thân tồn tại - eventOn/getButtonEvent của SillyTavern Assistant thường được inject ở tầng này */
var SELF_WIN = null;
try {
  SELF_WIN = (typeof window !== 'undefined' && window) ? window
    : ((typeof globalThis !== 'undefined') ? globalThis : null);
} catch (e) { SELF_WIN = null; }

var HOST = resolveHostWindow();
var DOC = null;
try { DOC = HOST.document; } catch (e) { DOC = null; }
if (!DOC) { try { DOC = document; } catch (e) {} }

/* ---------------- Storage ---------------- */

var CFG_DEFAULT = {
  enabled: true,          // Công tắc tổng
  pin: true,              // Khóa chết tham số routing (xóa models[] / allow_fallbacks=false)
  think: 'off',           // off | high (chỉ bù khi thiếu trường)
  refract: 'off',         // off | light | mid (mức vi nhiễu 3 luồng)
  observe: true,          // Trình quan sát zero-lock
  dualBase: '',           // Fingerprint kênh đôi: base url
  dualKey: '',            // Fingerprint kênh đôi: key
  min: false,             // Bảng điều khiển có thu gọn thành bong bóng nhỏ hay không
  xhr: false,             // Có hook XMLHttpRequest không (mặc định tắt; chỉ dùng fetch sẽ ổn định hơn)
  safe: false,            // Chế độ an toàn: hoàn toàn không hook, chỉ giữ lại bảng điều khiển và banner (dùng để debug)
  mx: null,               // Cửa sổ nổi trên mobile left (px, null=mặc định góc dưới bên phải)
  my: null,               // Cửa sổ nổi trên mobile top
  keep: 30
};

var cfg = null;

function readCfg() {
  var d = {};
  for (var k in CFG_DEFAULT) d[k] = CFG_DEFAULT[k];
  try {
    var raw = HOST.localStorage.getItem(CFG_KEY);
    if (raw) {
      var s = JSON.parse(raw);
      for (var k2 in s) if (Object.prototype.hasOwnProperty.call(CFG_DEFAULT, k2)) d[k2] = s[k2];
      // Migration phiên bản: khi config v1 không có trường refract, ép quay về off (không dùng lại công tắc noise cũ)
      if (!('refract' in s)) d.refract = 'off';
    }
  } catch (e) {}
  return d;
}

function saveCfg() {
  try { HOST.localStorage.setItem(CFG_KEY, JSON.stringify(cfg)); } catch (e) {}
}

function readLog() {
  try {
    var raw = HOST.localStorage.getItem(LOG_KEY);
    if (!raw) return [];
    var arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr : [];
  } catch (e) { return []; }
}

function pushLog(rec) {
  var arr = readLog();
  arr.unshift(rec);              /* Mới nhất ở trước: bảng điều khiển lấy trực tiếp N mục đầu */
  var cap = MAX_LOG;
  if (typeof cfg === 'object' && cfg && cfg.keep) cap = Math.min(MAX_LOG, Math.max(10, cfg.keep));
  if (arr.length > cap) arr.length = cap;
  try { HOST.localStorage.setItem(LOG_KEY, JSON.stringify(arr)); } catch (e) {}
  return arr;
}

cfg = readCfg();

/* ---------------- Chuẩn hóa model ---------------- */

var KNOWN_PREFIX = /^(?:models\/|google\/|openrouter\/|vertex_ai\/|vertex\/|gemini\/|custom\/|litellm\/|fireworks\/|together\/|pggo-|bdgo-|aihubmix-|proxy-)/;

function normModel(s) {
  var t = String(s == null ? '' : s).trim();
  if (!t) return '';
  try { t = decodeURIComponent(t); } catch (e) {}
  t = t.toLowerCase().split('?')[0].replace(/^https?:\/\/[^/]+\//, '');
  for (var i = 0; i < 4; i++) {
    var before = t;
    t = t.replace(KNOWN_PREFIX, '');
    if (t === before) break;
  }
  t = t.replace(/:(generatecontent|streamgeneratecontent|counttokens).*$/, '');
  return t.trim();
}

function isOpaqueModel(s) {
  var m = normModel(s);
  if (!m) return true;
  return /^(?:auto|router|default|unknown|any|best|lb)$/.test(m);
}

function isNonChatModel(s) {
  var m = normModel(s);
  return /(?:embedding|embedcontent|imagen|veo|aqa|image-only|tts|audio-only)/.test(m);
}

function isGeminiLike(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return false;
  if (/(?:gemma|claude|deepseek|gpt|o1|o3|qwen|llama|glm|ernie)/.test(m)) return false;
  return /gemini/.test(m) || /argon|flash|lite|pro/.test(m) === false ? /gemini/.test(m) : /gemini/.test(m);
}

/* Phân cấp: 1=lite/8b, 2=flash, 3=pro, 4=argon/ultra, 0=Không rõ */
function tierOf(s) {
  var m = normModel(s);
  if (!m || isOpaqueModel(m)) return 0;
  if (/(?:flash[-_. ]?lite|flash[-_. ]?8b|\blite\b|\bnano\b)/.test(m)) return 1;
  if (/\b(?:argon|ultra)\b/.test(m)) return 4;
  if (/\bpro\b/.test(m)) return 3;
  if (/\bflash\b/.test(m)) return 2;
  return 0;
}

function isProLike(s) {
  var t = tierOf(s);
  return t === 3 || t === 4;
}

function shortName(s) {
  var m = normModel(s);
  if (!m) return '—';
  return m.length > 26 ? m.slice(0, 25) + '…' : m;
}

/* ---------------- Ước tính token (CJK 0.85 / Latin 1÷3.5 / Khác 0.9) ---------------- */

function estimateTokens(str) {
  if (typeof str !== 'string' || !str) return 0;
  var cjk = 0, latin = 0, other = 0;
  for (var i = 0; i < str.length; i++) {
    var cp = str.codePointAt ? str.codePointAt(i) : str.charCodeAt(i);
    if (cp > 0xffff) i++;
    if (cp >= 0x3400 && cp <= 0x9fff) cjk++;
    else if (cp <= 0x7f) latin++;
    else other++;
  }
  return Math.ceil(cjk * 0.85 + latin / 3.5 + other * 0.9);
}

/* ---------------- Vùng bảo vệ ----------------
 * 12 loại: YAML frontmatter / Code block / Inline code / Macro SillyTavern / Tag state machine / Fence giao thức
 *         / Bản thân thẻ XML / Comment và định nghĩa trích dẫn có sẵn / URL và liên kết / LaTeX / Lời thoại trong ngoặc kép / Tag chưa đóng kéo dài đến hết
 */

var HARD_TAGS = 'UpdateVariable|JSONPatch|jsonpatch|mvu|status|StatusBlock|Status_block|state|panel|options|tool_call|function_call|run_tool_replacement|worldcustomfunction|worldsystem|KonataExtraInformation|IzumiEdit|stat_data|delta_data|variables|StatusPlaceHolderImpl|thinking|think|dream_think|simple_thinking|interleav|Interleaved_thinking|interactive_input';

var SPAN_RULES = [
  /(^|\n)([ \t]{0,3})(`{3,}|~{3,})[^\n]*\n[\s\S]*?\n\2\3[ \t]*(?=\n|$)/g,
  /(`+)([^`\n]+?)\1/g,
  /\{\{[\s\S]{0,4000}?\}\}|<%[\s\S]{0,4000}?%>/g,
  new RegExp('<(' + HARD_TAGS + ')\\b[^>]*>[\\s\\S]*?<\\/\\1\\s*>', 'gi'),
  /<<<\|catgodml\|[\s\S]*?>>>|\[\[IZUMI_CHAT_INDEX_V1\]\]/g,
  /<\/?[A-Za-z\u4e00-\u9fa5][\w:\u4e00-\u9fa5.-]*(?:\s[^<>]{0,400})?>/g,
  /<!--[\s\S]*?-->|^\[\/\/\]:\s*#\s*\([^\n]*\)/gm,
  /\bhttps?:\/\/[^\s<>()]+|!?\[[^\]]*\]\([^)]+\)/g,
  /\$\$[\s\S]*?\$\$|\$[^$\n]{1,400}\$|\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]/g,
  /“[^”\n]{1,600}”|「[^」\n]{1,600}」|『[^』\n]{1,600}』|"[^"\n]{1,600}"/g
];

function collectSpans(text) {
  var spans = [];
  if (typeof text !== 'string' || !text) return spans;

  var yaml = /^---[ \t]*\r?\n[\s\S]{1,4000}?\r?\n---[ \t]*(?:\r?\n|$)/.exec(text);
  if (yaml) spans.push([0, yaml[0].length]);

  var trimmed = text.trim();
  if ((trimmed.charAt(0) === '{' && trimmed.slice(-1) === '}') ||
      (trimmed.charAt(0) === '[' && trimmed.slice(-1) === ']')) {
    try { JSON.parse(trimmed); return [[0, text.length]]; } catch (e) {}
  }

  for (var r = 0; r < SPAN_RULES.length; r++) {
    var re = new RegExp(SPAN_RULES[r].source, SPAN_RULES[r].flags);
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 4000) {
      var s = m.index + (m[1] && m[1].length && SPAN_RULES[r] === SPAN_RULES[0] ? m[2].length : 0);
      spans.push([m.index, m.index + m[0].length]);
      if (m[0].length === 0) re.lastIndex++;
    }
  }

  // Tag cứng chưa đóng: bảo vệ liên tục từ thẻ mở đến cuối
  var openRe = new RegExp('<(' + HARD_TAGS + ')\\b[^>]*>', 'gi');
  var om;
  var oguard = 0;
  while ((om = openRe.exec(text)) !== null && oguard++ < 500) {
    var name = om[1];
    var closeRe = new RegExp('<\\/' + name + '\\s*>', 'i');
    var after = text.slice(om.index + om[0].length);
    if (!closeRe.test(after)) spans.push([om.index, text.length]);
  }

  spans.sort(function (a, b) { return a[0] - b[0] || a[1] - b[1]; });
  var merged = [];
  for (var i = 0; i < spans.length; i++) {
    var cur = spans[i];
    if (cur[1] <= cur[0]) continue;
    if (merged.length && cur[0] <= merged[merged.length - 1][1]) {
      merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], cur[1]);
    } else merged.push([cur[0], cur[1]]);
  }
  return merged;
}

function isProtected(spans, start, end) {
  if (!spans || !spans.length) return false;
  var lo = 0, hi = spans.length - 1;
  var qs = Math.min(start, end);
  var qe = Math.max(start + 1, end);
  while (lo <= hi) {
    var mid = (lo + hi) >> 1;
    if (qe <= spans[mid][0]) hi = mid - 1;
    else if (qs >= spans[mid][1]) lo = mid + 1;
    else return true;
  }
  return false;
}

/* ---------------- Chấm điểm vùng tĩnh ---------------- */

var INSTR_WORDS = /bắt buộc|cấm|không được|nghiêm cấm|xin đừng|nhất định|nghiêm ngặt|quy tắc|chuẩn tắc|quy chuẩn|định dạng|output|thiết lập|yêu cầu|chú ý|quan trọng|ưu tiên|ví dụ|chỉ thị|tuân thủ|nhập vai|miêu tả|văn phong|số từ|đoạn văn|\b(?:must|shall|require|format|rule|instruction|guideline|never|do not|output|response|system|character|roleplay|constraint)\b/gi;
var NARR_WORDS = /nói|hỏi|nhìn|hướng về|bước vào|quay người|mỉm cười|thì thào|khẽ nói|im lặng|ngẩng đầu|thở dài|ánh mắt|tầm mắt|hơi thở|ngón tay|ngoài cửa sổ|khóe miệng|gật đầu|lắc đầu|nghĩ thầm|âm thanh|\b(?:said|asked|looked|smiled|whispered|sighed|walked|turned|nodded|eyes|voice|hand|felt|thought)\b/gi;
var QUOTE_RE = /“[^”\n]{2,200}”|「[^」\n]{2,200}」|"[^"\n]{2,200}"/g;
var MARKUP_RE = /^(?:[ \t]*#{1,6}[ \t]+\S|[ \t]*[-+*][ \t]+\S|[ \t]*\d+[.)][ \t]+\S|[ \t]*>[ \t]+\S)|<\/?[A-Za-z][\w:.-]*\b/gm;

function density(text, re) {
  if (!text) return 0;
  var hits = text.match(new RegExp(re.source, re.flags));
  return ((hits ? hits.length : 0) * 1000) / Math.max(80, text.length);
}

function staticScore(node, total) {
  var text = node.text || '';
  if (text.replace(/\s/g, '').length < 40) return -50;
  if (node.isLastUser) return -100;
  if (node.isPrefill) return -90;

  var score = 0;
  var role = node.role;
  if (role === 'system' || role === 'developer') score += 42;
  else if (role === 'user') score += 8;
  else if (role === 'assistant' || role === 'model') score -= 25;

  if (node.index === 0) score += 20;
  else if (node.index < 3) score += 14;

  var ins = density(text, INSTR_WORDS);
  var nar = density(text, NARR_WORDS);
  var quo = density(text, QUOTE_RE);
  var mark = density(text, MARKUP_RE);

  score += Math.min(32, ins * 3.8);
  score += Math.min(16, mark * 2.5);
  score -= Math.min(38, nar * 2.6 + quo * 3.2);
  if (ins >= 3.5 && mark >= 2.0 && nar < 2.0) score += 18;

  return Math.max(-100, Math.min(100, score));
}

function hasRuleMarkup(text) {
  if (typeof text !== 'string' || text.length < 80) return false;
  if (/^[ \t]*#{1,6}[ \t]+\S/m.test(text)) return true;
  var lists = text.match(/^[ \t]*(?:[-+*]|\d+[.)])[ \t]+\S/gm);
  if (lists && lists.length >= 2) return true;
  return /<(?:rules?|instructions?|guidelines?|system|config|writing_style|world_info)\b/i.test(text);
}

/* Dải lịch sử: tin nhắn assistant đầu tiên cùng các tin nhắn sau nó (bao gồm cả tin nhắn user kích hoạt nó) đều được coi là lịch sử */
function findHistoryBand(nodes) {
  var firstAssistant = -1;
  for (var i = 0; i < nodes.length; i++) {
    if (nodes[i].role === 'assistant' || nodes[i].role === 'model') { firstAssistant = i; break; }
  }
  if (firstAssistant < 0) return null;
  var start = firstAssistant;
  for (var j = firstAssistant - 1; j >= 0; j--) {
    if (nodes[j].role === 'user') { start = j; break; }
  }
  var lastUser = -1;
  for (var k = nodes.length - 1; k >= 0; k--) if (nodes[k].isLastUser) { lastUser = k; break; }
  var end = lastUser >= 0 ? lastUser - 1 : nodes.length - 1;
  if (end < start) return null;
  return { start: start, end: end, memberCount: end - start + 1 };
}

/* ---------------- Lựa chọn vùng ---------------- */

function getMsgText(m) {
  if (!m) return '';
  if (typeof m.content === 'string') return m.content;
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      var p = m.content[i];
      if (p && p.type === 'text' && typeof p.text === 'string') return p.text;
    }
  }
  if (typeof m.text === 'string') return m.text;
  return '';
}

function pickZones(inner, channel, maxZones) {
  var zones = [];
  var msgs = Array.isArray(inner.messages) ? inner.messages : null;

  if (!msgs && (Array.isArray(inner.contents) || inner.systemInstruction)) {
    var si = inner.systemInstruction;
    if (si && Array.isArray(si.parts)) {
      for (var p = 0; p < si.parts.length; p++) {
        (function (part) {
          if (!part || typeof part.text !== 'string') return;
          if (part.text.replace(/\s/g, '').length < 60) return;
          zones.push({ get: function () { return part.text; }, set: function (v) { part.text = v; }, score: 100, why: 'systemInstruction.parts[' + p + ']' });
        })(si.parts[p]);
      }
    } else if (si && typeof si.text === 'string' && si.text.replace(/\s/g, '').length >= 60) {
      zones.push({ get: function () { return si.text; }, set: function (v) { si.text = v; }, score: 100, why: 'systemInstruction.text' });
    }
    return zones.slice(0, maxZones);
  }

  if (!msgs || !msgs.length) return zones;

  var lastUserIdx = -1;
  for (var i = msgs.length - 1; i >= 0; i--) {
    var r = String(msgs[i] && msgs[i].role || '').toLowerCase();
    if (r === 'user' && getMsgText(msgs[i]).trim()) { lastUserIdx = i; break; }
  }

  var nodes = [];
  for (var j = 0; j < msgs.length; j++) {
    var m = msgs[j];
    if (!m || typeof m !== 'object') continue;
    var role = String(m.role || 'user').toLowerCase();
    if (role === 'tool' || role === 'function' || m.tool_calls || m.function_call) continue;
    var text = getMsgText(m);
    if (!text || !text.trim()) continue;
    nodes.push({
      index: j, role: role, text: text,
      isLastUser: j === lastUserIdx,
      isPrefill: (role === 'assistant' || role === 'model') && j === msgs.length - 1 && j > lastUserIdx,
      msg: m
    });
  }

  var band = findHistoryBand(nodes);
  var headIdx = band ? band.start : nodes.length;

  for (var k = 0; k < nodes.length; k++) {
    var n = nodes[k];
    if (n.isLastUser || n.isPrefill) continue;
    if (n.role === 'assistant' || n.role === 'model') continue;
    if (band && k >= band.start && k <= band.end) continue;
    var sc = staticScore(n, nodes.length);
    if (sc < 52) continue;
    if (n.role === 'user' && !hasRuleMarkup(n.text)) continue;
    zones.push({
      score: sc,
      why: 'msg[' + n.index + '](' + n.role + ',' + Math.round(sc) + ')',
      get: (function (msg) { return function () { return getMsgText(msg); }; })(n.msg),
      set: (function (msg) { return function (v) { if (typeof msg.content === 'string') msg.content = v; else msg.content = [{ type: 'text', text: v }]; }; })(n.msg)
    });
  }

  zones.sort(function (a, b) { return b.score - a.score; });
  return zones.slice(0, maxZones);
}

/* ===== 2_refract.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 2/4 Refraction
 * Vi nhiễu 3 luồng (W Khoảng trắng / L Từ nối / A Điểm neo) + Cắt giảm ngân sách + Bảo vệ signature cấp khối + Tính lũy đẳng
 * ========================================================================== */

var PROFILE = {
  off:   { tokens: 0,  w: 0, l: 0, a: 0, zones: 0 },
  light: { tokens: 18, w: 3, l: 1, a: 1, zones: 1 },
  mid:   { tokens: 56, w: 6, l: 2, a: 2, zones: 2 }
};
var HARD_TOKEN_CAP = 120;

var ANCHOR_TOPICS = ['rules', 'context', 'section', 'layout', 'style', 'frame', 'notes', 'spec'];
var ANCHOR_KINDS = ['part', 'block', 'node', 'unit', 'seg', 'item'];

/* Từ nối văn bản: biến đổi ngữ nghĩa bằng 0, tuyệt đối không chạm vào từ tình thái/phủ định/nghĩa vụ */
var DISCOURSE = [
  [/(^|[,.;:!?\n\s])(Ngoài ra,|Hơn nữa,)/g, ['Ngoài ra,', 'Hơn nữa,']],
  [/(^|[,.;:!?\n\s])(Do đó,|Vì vậy,|Cho nên,)/g, ['Do đó,', 'Vì vậy,', 'Cho nên,']],
  [/(^|[,.;:!?\n\s])(Tóm lại,|Tổng kết lại,|Nói một cách ngắn gọn,)/g, ['Tóm lại,', 'Tổng kết lại,', 'Nói một cách ngắn gọn,']],
  [/(^|[,.;:!?\n\s])(Ví dụ,|Chẳng hạn,|Thí dụ,)/g, ['Ví dụ,', 'Chẳng hạn,', 'Thí dụ,']],
  [/(^|[,.;:!?\n\s])(Đồng thời,|Cùng lúc đó,)/g, ['Đồng thời,', 'Cùng lúc đó,']],
  [/(^|[,.;:!?\n\s])(Nói cách khác,|Hay nói một cách khác,)/g, ['Nói cách khác,', 'Hay nói một cách khác,']],
  [/(\b)(For example,)/g, ['For example,', 'For instance,']],
  [/(\b)(Therefore,)/g, ['Therefore,', 'Thus,', 'Hence,']],
  [/(\b)(However,)/g, ['However,', 'Nevertheless,']]
];

var ANCHOR_STRIP = /(?:^|\n)[ \t]*(?:<!--[ \t]*(?:ctx|ref):[^>]*-->|\[\/\/\]:[ \t]*#[ \t]*\((?:ctx|ref):[^)]*\))[ \t]*(?=\n|$)/g;

var W_STRIP_LIST = /^([ \t]*(?:[-*+]|\d+\.|>))[ \t]{2,}/gm;
var W_STRIP_GAP = /\n[ \t]{1,3}\n/g;

function stripArtifacts(text) {
  if (typeof text !== 'string') return text;

  /* 1) Xóa điểm neo trên toàn dòng (cùng với ký tự xuống dòng mà nó tạo ra), tránh để lại dòng trống ở dòng đầu tiên */
  var lines = text.split('\n');
  var kept = [];
  for (var i = 0; i < lines.length; i++) {
    if (/^[ \t]*(?:<!--[ \t]*(?:ctx|ref):[^>]*-->|\[\/\/\]:[ \t]*#[ \t]*\((?:ctx|ref):[^)]*\))[ \t]*$/.test(lines[i])) continue;
    kept.push(lines[i]);
  }
  var out = kept.join('\n');

  /* 2) Khôi phục luồng khoảng trắng: khoảng cách giữa các đoạn và khoảng trắng thừa sau ký hiệu danh sách được rút về 1 khoảng trắng */
  out = out.replace(W_STRIP_GAP, '\n\n').replace(W_STRIP_LIST, '$1 ');
  return out;
}

/* ---------------- Nguồn ngẫu nhiên (seeded LCG, có thể tái lập) ---------------- */

function makeRng(seed) {
  var s = (seed >>> 0) || 0x20261101;
  return function () {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
}

/* ---------------- Signature cấp khối ---------------- */

function blockSignature(text) {
  var lines = String(text || '').split('\n');
  var h = [0, 0, 0, 0, 0, 0], li = 0, q = 0, tb = 0, fence = 0;
  for (var i = 0; i < lines.length; i++) {
    var ln = lines[i];
    if (!ln.trim()) continue;
    if (/^[ \t]*(?:<!--|\/\/\]:[ \t]*#)/.test(ln)) continue;
    var mh = /^[ \t]*(#{1,6})[ \t]+\S/.exec(ln);
    if (mh) { h[mh[1].length - 1]++; continue; }
    if (/^[ \t]*(?:[-+*]|\d{1,4}[.)])[ \t]+\S/.test(ln)) { li++; continue; }
    if (/^[ \t]*>/.test(ln)) { q++; continue; }
    if (/^[ \t]*\|.*\|[ \t]*$/.test(ln)) { tb++; continue; }
    if (/^[ \t]*(?:`{3,}|~{3,})/.test(ln)) { fence++; continue; }
  }
  return h.join(',') + '|' + li + '|' + q + '|' + tb + '|' + fence;
}

/* ---------------- Luồng W: Khoảng trắng cấu trúc cấp khối ---------------- */

function findWSites(text, spans) {
  var sites = [];
  var patterns = [
    /^(#{1,6})([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}[-+*])([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}\d{1,4}[.)])([ \t]{1,2})(?=\S)/gm,
    /^([ \t]{0,3}>)([ \t]{1,2})(?=\S)/gm
  ];
  for (var i = 0; i < patterns.length; i++) {
    var re = new RegExp(patterns[i].source, 'gm');
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 500) {
      var pos = m.index + m[1].length + m[2].length;
      if (isProtected(spans, m.index, pos)) continue;
      sites.push({ pos: pos, kind: 'inline' });
    }
  }
  var gapRe = /([^\n>`~|}])\n(\n)(?=\S)/g;
  var gm;
  var g2 = 0;
  while ((gm = gapRe.exec(text)) !== null && g2++ < 500) {
    var gp = gm.index + 1;
    if (isProtected(spans, gp - 1, gp + 2)) continue;
    sites.push({ pos: gp + 1, kind: 'gap' });
  }
  sites.sort(function (a, b) { return a.pos - b.pos; });
  return sites;
}

function planW(text, spans, max, rng) {
  if (max <= 0) return [];
  var sites = findWSites(text, spans);
  if (!sites.length) return [];
  var picked = [];
  var startIdx = Math.floor(rng() * sites.length);
  for (var step = 0; step < sites.length && picked.length < max; step++) {
    var s = sites[(startIdx + step) % sites.length];
    var clash = false;
    for (var k = 0; k < picked.length; k++) if (Math.abs(picked[k].pos - s.pos) < 36) { clash = true; break; }
    if (clash) continue;
    picked.push(s);
  }
  return picked.map(function (s) {
    return {
      track: 'W', start: s.pos, end: s.pos,
      text: s.kind === 'gap' ? ' ' : ' ',
      weight: 1
    };
  });
}

/* ---------------- Luồng L: Luân chuyển từ nối văn bản ---------------- */

function planL(text, spans, max, rng) {
  if (max <= 0) return [];
  var cands = [];
  for (var i = 0; i < DISCOURSE.length; i++) {
    var re = new RegExp(DISCOURSE[i][0].source, DISCOURSE[i][0].flags);
    var alts = DISCOURSE[i][1];
    var m;
    var guard = 0;
    while ((m = re.exec(text)) !== null && guard++ < 200) {
      var lead = m[1] || '';
      var word = m[2] || '';
      if (!word) continue;
      var start = m.index + lead.length;
      var end = start + word.length;
      if (isProtected(spans, start, end)) continue;
      var pool = [];
      for (var a = 0; a < alts.length; a++) if (alts[a] !== word) pool.push(alts[a]);
      if (!pool.length) continue;
      cands.push({ start: start, end: end, text: pool[Math.floor(rng() * pool.length)] });
    }
  }
  if (!cands.length) return [];
  var picked = [];
  var offset = Math.floor(rng() * cands.length);
  for (var s = 0; s < cands.length && picked.length < max; s++) {
    var c = cands[(offset + s) % cands.length];
    var clash2 = false;
    for (var p = 0; p < picked.length; p++) if (Math.abs(picked[p].start - c.start) < 60) { clash2 = true; break; }
    if (clash2) continue;
    picked.push(c);
  }
  return picked.map(function (c) {
    return { track: 'L', start: c.start, end: c.end, text: c.text, weight: 1 };
  });
}

/* ---------------- Luồng A: Điểm neo an toàn cấp khối ---------------- */

function buildAnchor(rng, html) {
  var topic = ANCHOR_TOPICS[Math.floor(rng() * ANCHOR_TOPICS.length)];
  var kind = ANCHOR_KINDS[Math.floor(rng() * ANCHOR_KINDS.length)];
  var hex = Math.floor(rng() * 0xffff).toString(16);
  while (hex.length < 4) hex = '0' + hex;
  var tag = rng() < 0.5 ? 'ctx' : 'ref';
  return html ? '<!-- ' + tag + ': ' + topic + ' / ' + kind + ' ' + hex + ' -->'
              : '[//]: # (' + tag + ': ' + topic + ' / ' + kind + ' ' + hex + ')';
}

function isBlockLine(line) {
  var s = String(line || '');
  return /^[ \t]{0,3}(?:[-+*]|\d{1,4}[.)])[ \t]+\S/.test(s) ||
         /^[ \t]{0,3}>/.test(s) ||
         /^[ \t]{0,3}\|.*\|[ \t]*$/.test(s) ||
         /^[ \t]{2,}\S/.test(s);
}

function findAnchorSites(text, spans) {
  var out = [];
  var idx = -1;
  var guard = 0;
  while ((idx = text.indexOf('\n', idx + 1)) !== -1 && guard++ < 4000) {
    if (isProtected(spans, idx, idx + 1)) continue;
    var lineStart = text.lastIndexOf('\n', idx - 1) + 1;
    var prevLine = text.slice(lineStart, idx);
    var nextNl = text.indexOf('\n', idx + 1);
    var nextLine = text.slice(idx + 1, nextNl === -1 ? text.length : nextNl);
    var prevTrim = prevLine.replace(/\s+$/, '');
    if (/[:：<{`\\]$/.test(prevTrim)) continue;
    if (isBlockLine(prevLine) && (isBlockLine(nextLine) || !nextLine.trim())) continue;
    var prevHeading = /^[ \t]{0,3}#{1,6}[ \t]+\S/.test(prevLine);
    var nextHeading = /^[ \t]{0,3}#{1,6}[ \t]+\S/.test(nextLine);
    var blankBoundary = !prevTrim && !isBlockLine(nextLine);
    if (prevHeading || nextHeading || blankBoundary) out.push(idx);
  }
  return out;
}

function planA(text, spans, isHead, max, rng) {
  if (max <= 0) return [];
  var sites = findAnchorSites(text, spans);
  var html = rng() < 0.5;
  var acts = [];
  if (isHead && !isProtected(spans, 0, 1)) {
    var a0 = buildAnchor(rng, html) + '\n';
    acts.push({ track: 'A', start: 0, end: 0, text: a0, weight: estimateTokens(a0) });
    return acts;
  }
  if (!sites.length) return acts;
  var pool = [];
  for (var i = 0; i < sites.length; i++) {
    if (sites[i] >= 4 && sites[i] <= 320) pool.push(sites[i]);
  }
  var target = pool.length ? pool[Math.floor(rng() * pool.length)] : sites[0];
  var ins = '\n' + buildAnchor(rng, !html);
  acts.push({ track: 'A', start: target, end: target, text: ins, weight: estimateTokens(ins) });
  return acts;
}

/* ---------------- Áp dụng (bao gồm cắt giảm ngân sách và bảo vệ signature) ---------------- */

function refractZone(text, opt, rng) {
  var empty = { changed: false, text: text, added: 0, edits: 0, tracks: { W: 0, L: 0, A: 0 } };
  var cleaned = stripArtifacts(text);
  if (typeof cleaned !== 'string' || cleaned.replace(/\s/g, '').length < 40) return empty;

  var spans = collectSpans(cleaned);
  if (spans.length === 1 && spans[0][0] === 0 && spans[0][1] >= cleaned.length) return empty;

  var acts = [];
  if (opt.w > 0) acts = acts.concat(planW(cleaned, spans, opt.w, rng));
  if (opt.l > 0) acts = acts.concat(planL(cleaned, spans, opt.l, rng));
  if (opt.a > 0) acts = acts.concat(planA(cleaned, spans, opt.isHead, opt.a, rng));
  if (!acts.length) return empty;

  var total = 0;
  for (var i = 0; i < acts.length; i++) total += acts[i].weight;
  while (total > opt.budget && acts.length) {
    var dropA = -1, dropL = -1;
    for (var j = 0; j < acts.length; j++) {
      if (acts[j].track === 'A' && dropA < 0) dropA = j;
      if (acts[j].track === 'L' && dropL < 0) dropL = j;
    }
    var di = dropA >= 0 ? dropA : (dropL >= 0 ? dropL : acts.length - 1);
    total -= acts[di].weight;
    acts.splice(di, 1);
  }
  if (!acts.length) return empty;

  acts.sort(function (x, y) { return y.start - x.start || y.end - x.end; });
  var out = cleaned;
  var lastStart = 1e9;
  var applied = 0;
  var tracks = { W: 0, L: 0, A: 0 };
  for (var k = 0; k < acts.length; k++) {
    var act = acts[k];
    if (act.end > lastStart) continue;
    if (act.start > 0 && isProtected(spans, act.start, act.end)) continue;
    out = out.slice(0, act.start) + act.text + out.slice(act.end);
    lastStart = act.start;
    applied++;
    tracks[act.track]++;
  }
  if (!applied || out === cleaned) return empty;

  if (blockSignature(cleaned) !== blockSignature(out)) return empty;

  return { changed: true, text: out, added: Math.max(1, Math.ceil(total)), edits: applied, tracks: tracks };
}

/* ---------------- Viết lại request ---------------- */

function textOfMsg(m) {
  if (!m) return '';
  if (typeof m.content === 'string') return m.content;
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      if (m.content[i] && m.content[i].type === 'text') return m.content[i].text || '';
    }
  }
  return '';
}

function setMsgText(m, v) {
  if (typeof m.content === 'string') { m.content = v; return; }
  if (Array.isArray(m.content)) {
    for (var i = 0; i < m.content.length; i++) {
      if (m.content[i] && m.content[i].type === 'text') { m.content[i].text = v; return; }
    }
  }
}

function deriveBase(url, body) {
  try {
    if (body && typeof body.reverse_proxy === 'string' && body.reverse_proxy) return body.reverse_proxy.replace(/\/+$/, '');
    var u = new URL(url, HOST.location ? HOST.location.href : 'http://localhost');
    var path = u.pathname;
    var cut = path.indexOf('/api/backends/chat-completions');
    if (cut >= 0) return u.origin;
    return u.origin;
  } catch (e) { return cfg.dualBase || ''; }
}

function planRequest(rawBody, url) {
  var out = { changed: [], model: '', base: '', body: rawBody };
  if (!rawBody) return out;
  var body;
  try { body = JSON.parse(rawBody); } catch (e) { return out; }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return out;

  out.model = String(body.model || body.model_name || '');
  out.base = deriveBase(url, body);

  if (cfg.pin) {
    if (Array.isArray(body.models) && body.models.length) { delete body.models; out.changed.push('Xóa models[]'); }
    if (Object.prototype.hasOwnProperty.call(body, 'allow_fallbacks') && body.allow_fallbacks !== false) {
      body.allow_fallbacks = false; out.changed.push('allow_fallbacks=false');
    }
    if (Object.prototype.hasOwnProperty.call(body, 'openrouter_allow_fallbacks') && body.openrouter_allow_fallbacks !== false) {
      body.openrouter_allow_fallbacks = false; out.changed.push('openrouter_allow_fallbacks=false');
    }
    if (Object.prototype.hasOwnProperty.call(body, 'openrouter_use_fallback') && body.openrouter_use_fallback !== false) {
      body.openrouter_use_fallback = false; out.changed.push('openrouter_use_fallback=false');
    }
    if (body.route !== undefined && body.route !== null) { delete body.route; out.changed.push('Xóa route'); }
  }

  if (cfg.think === 'high') {
    var hasThink = body.thinking !== undefined || body.thinkingConfig !== undefined || body.reasoning_effort !== undefined;
    if (!hasThink) { body.reasoning_effort = 'high'; out.changed.push('reasoning_effort=high'); }
  }

  if (cfg.refract !== 'off') {
    var prof = PROFILE[cfg.refract] || PROFILE.off;
    var inner = body;
    if (body.request && typeof body.request === 'object' && !Array.isArray(body.request)) inner = body.request;
    var zones = pickZones(inner, '', prof.zones);
    var rng = makeRng(Date.now() ^ 0x5f3759df);
    var added = 0, edits = 0, touched = 0, tk = { W: 0, L: 0, A: 0 };
    var budget = Math.min(prof.tokens, HARD_TOKEN_CAP);
    for (var i = 0; i < zones.length; i++) {
      if (budget <= 0) break;
      var before = zones[i].get();
      var res = refractZone(before, {
        w: prof.w, l: prof.l, a: prof.a, isHead: i === 0, budget: budget
      }, rng);
      if (!res.changed) continue;
      zones[i].set(res.text);
      touched++;
      added += res.added;
      edits += res.edits;
      budget -= res.added;
      tk.W += res.tracks.W; tk.L += res.tracks.L; tk.A += res.tracks.A;
    }
    if (touched > 0) {
      out.changed.push('Vi nhiễu ' + touched + ' vùng/W' + tk.W + ' · L' + tk.L + ' · A' + tk.A + '/+' + added + ' tok');
    }
  }

  /* Mấu chốt: chỉ cần thay đổi body thì bắt buộc phải tuần tự hóa ngược lại; nếu không việc khóa tham số chỉ mới sửa đổi đối tượng trên bộ nhớ */
  if (out.changed.length) out.body = JSON.stringify(body);

  return out;
}

/* ===== 3_net.js ===== */
/* ============================================================================
 * Anti-Route v6.0 — 3/4 Net
 * Hook request / Trình quan sát host zero-lock / Bộ phán đoán / Hai đầu dò
 * Mấu chốt: HTTP 200 không đụng vào res.body, không gọi tee() và clone()
 * ========================================================================== */

var origFetch = null;
var hooked = false;
var booted = false;
var lastReq = null;
var inflight = 0;

function nowMs() { return Date.now(); }

function urlOf(input) {
  try {
    if (typeof input === 'string') return input;
    if (input && typeof input.url === 'string') return input.url;
  } catch (e) {}
  return '';
}

function isGenerateUrl(u) {
  return /\/chat-completions\/generate\b/.test(String(u || ''));
}

/* ---------------- Bằng chứng và phán đoán ---------------- */

function newEvidence(model, status, transport) {
  return {
    requestedModel: model, observed: [], status: status, transport: transport,
    sawText: false, hasThink: false, hasReasonField: false,
    outputChars: 0, thoughtTok: 0, firstMs: 0, totalMs: 0, error: ''
  };
}

var VERDICT = {
  same:    { label: 'Khớp', color: 'ok' },
  diff:    { label: 'Bị tráo', color: 'bad' },
  thin:    { label: 'Không suy nghĩ', color: 'warn' },
  unknown: { label: 'Không rõ', color: 'gray' },
  quota:   { label: 'Hạn ngạch', color: 'warn' },
  blocked: { label: 'Bị chặn', color: 'bad' },
  gate:    { label: 'Lỗi gateway', color: 'bad' },
  empty:   { label: 'Phản hồi rỗng', color: 'bad' },
  error:   { label: 'Thất bại', color: 'bad' }
};

function verdictOf(ev) {
  if (ev.error) return { code: 'error', note: ev.error };
  if (ev.status === 429) return { code: 'quota', note: 'HTTP 429' };
  if (ev.status >= 500) return { code: 'gate', note: 'HTTP ' + ev.status };
  if (ev.blocked) return { code: 'blocked', note: ev.blocked };
  if (!ev.sawText && ev.status >= 400) return { code: 'error', note: 'HTTP ' + ev.status };
  if (!ev.sawText) return { code: 'empty', note: 'Không có nội dung' };

  var req = ev.requestedModel;
  var obs = ev.observed.filter(function (x) { return x && !/^(?:auto|router|default|unknown|any)$/i.test(String(x).trim()); });
  for (var i = 0; i < obs.length; i++) {
    var a = normModel(req), b = normModel(obs[i]);
    if (!a || !b) continue;
    if (a === b) {
      if (isProLike(a) && !ev.hasThink) return { code: 'thin', note: 'Model khớp nhưng không có chuỗi suy nghĩ' };
      return { code: 'same', note: shortName(obs[i]) };
    }
    var ta = tierOf(a), tb = tierOf(b);
    if (ta > 0 && tb > 0 && tb < ta) return { code: 'diff', note: shortName(obs[i]) + ' (T' + tb + '<T' + ta + ')' };
    if (ta > 0 && tb > 0) return { code: 'same', note: shortName(obs[i]) };
    return { code: 'unknown', note: 'Model khác biệt nhưng không thể phân cấp: ' + shortName(obs[i]) };
  }
  if (isProLike(req) && !ev.hasThink) return { code: 'thin', note: 'Không có định danh model và không có chuỗi suy nghĩ' };
  return { code: 'unknown', note: 'Upstream không trả về định danh model' };
}

function finish(ev, meta) {
  var v = verdictOf(ev);
  var rec = {
    at: nowMs(),
    req: shortName(ev.requestedModel),
    obs: ev.observed.length ? shortName(ev.observed[0]) : '—',
    code: v.code,
    verdict: (VERDICT[v.code] || VERDICT.unknown).label,
    note: v.note,
    status: ev.status,
    ttft: ev.firstMs,
    total: ev.totalMs,
    chars: ev.outputChars,
    think: ev.hasThink ? 1 : 0,
    changed: (meta && meta.changed) || [],
    edits: (meta && meta.edits) || 0,
    added: (meta && meta.added) || 0
  };
  pushLog(rec);
  render();
  var kind = (VERDICT[v.code] || VERDICT.unknown).color;
  if (v.code === 'diff' || v.code === 'blocked' || v.code === 'gate' || v.code === 'empty') {
    banner('🔴 ' + rec.verdict + ': ' + v.note + ' (Yêu cầu ' + rec.req + ')', kind);
  } else if (v.code === 'thin') {
    banner('🟠 ' + rec.verdict + ': ' + v.note + ' (Yêu cầu ' + rec.req + ')', kind);
  } else if (v.code === 'same') {
    banner('🟢 Khớp: ' + v.note + ' (' + (rec.ttft ? (rec.ttft / 1000).toFixed(1) + 's ký tự đầu, ' : '') + rec.chars + ' ký tự)', kind);
  } else {
    banner('⚪ ' + rec.verdict + ': ' + v.note, kind);
  }
  return rec;
}

/* ---------------- Phân tích error body (chỉ clone khi >=400) ---------------- */

function salvage(text, ev) {
  if (typeof text !== 'string' || !text) return;
  var mre = /"(?:modelVersion|model)"\s*:\s*"([^"]{1,120})"/g;
  var m;
  while ((m = mre.exec(text)) !== null) {
    var v = m[1].trim();
    if (v && ev.observed.indexOf(v) < 0) ev.observed.push(v);
  }
  if (/PROHIBITED_CONTENT|BLOCKLIST|SAFETY|SPII|RECITATION/.test(text)) {
    var bm = /(PROHIBITED_CONTENT|BLOCKLIST|SAFETY|SPII|RECITATION)/.exec(text);
    ev.blocked = bm ? bm[1] : 'BLOCKED';
  }
  if (!ev.sawText && /"(?:text|content|message)"\s*:\s*"[^"]/.test(text)) ev.sawText = true;
}

function readErrorBody(res, ev) {
  try {
    if (typeof res.clone !== 'function') return;
    res.clone().text().then(function (t) {
      salvage(t, ev);
      ev.sawText = ev.sawText || false;
      if (!ev.error) ev.error = '';
      finish(ev, null);
    }).catch(function () { finish(ev, null); });
  } catch (e) { finish(ev, null); }
}

/* ---------------- Trình quan sát host zero-lock ---------------- */

function stCtx() {
  try {
    var st = HOST.SillyTavern;
    if (st && typeof st.getContext === 'function') return st.getContext();
  } catch (e) {}
  return null;
}

function isBusy() {
  try {
    if (HOST.is_send_press || HOST.is_generating) return true;
    var body = DOC && DOC.body;
    if (body && body.classList && body.classList.contains('generating')) return true;
    var stop = DOC && DOC.getElementById && DOC.getElementById('mes_stop');
    if (stop && stop.style && stop.style.display !== 'none') return true;
  } catch (e) {}
  return false;
}

function startWatcher(ev, meta, reqStart) {
  var ctx = stCtx();
  if (!ctx || !Array.isArray(ctx.chat)) {
    ev.sawText = true;
    finish(ev, meta);
    return;
  }
  var baseLen = ctx.chat.length;
  var baseMes = baseLen ? String(ctx.chat[baseLen - 1] && ctx.chat[baseLen - 1].mes || '') : '';
  var lastLen = 0;
  var lastChange = nowMs();
  var sawBusy = false;
  var polls = 0;

  var timer = setInterval(function () {
    polls++;
    var t = nowMs();
    try {
      if (isBusy()) sawBusy = true;
      var c = stCtx();
      var chat = c && Array.isArray(c.chat) ? c.chat : null;
      if (chat && chat.length) {
        var msg = chat[chat.length - 1];
        var isAi = msg && !msg.is_user;
        var changed = chat.length > baseLen || (msg && String(msg.mes || '') !== baseMes);
        if (isAi && changed) {
          var mesStr = String(msg.mes || '');
          var reason = '';
          try {
            var ex = msg.extra || {};
            reason = String(ex.reasoning || ex.thinking || '');
            if (ex.model && ev.observed.indexOf(ex.model) < 0 && normModel(ex.model)) ev.observed.push(ex.model);
            if (ex.api_model && ev.observed.indexOf(ex.api_model) < 0) ev.observed.push(ex.api_model);
          } catch (e2) {}
          var joined = mesStr + (reason ? '\n' + reason : '');
          if (joined.length > 0 && !ev.firstMs) ev.firstMs = Math.max(1, t - reqStart);
          if (joined.length !== lastLen) { lastLen = joined.length; lastChange = t; }
          if (joined.length) {
            ev.sawText = true;
            ev.outputChars = joined.length;
            if (reason.trim() || /<(?:thinking|think|interleaving|SUOT)\b/i.test(mesStr)) {
              ev.hasThink = true;
              ev.hasReasonField = true;
              ev.thoughtTok = estimateTokens(reason);
            }
          }
        }
      }
      var settled = lastLen > 0 && (!isBusy() || t - lastChange > 2200);
      var stopped = sawBusy && !isBusy() && t - reqStart > 1200 && t - lastChange > 900;
      var noCtx = !stCtx() && polls >= 2;
      var timeout = t - reqStart > 120000;
      if (settled || stopped || noCtx || timeout) {
        clearInterval(timer);
        ev.totalMs = Math.max(1, t - reqStart);
        finish(ev, meta);
      }
    } catch (e3) {
      clearInterval(timer);
      try { ev.totalMs = Math.max(1, nowMs() - reqStart); finish(ev, meta); } catch (e4) {}
    }
  }, 150);
}

/* ---------------- Xử lý request ---------------- */

function handleFetch(next, thisArg, args) {
  var input = args[0];
  var init = args[1];
  var url = urlOf(input);
  if (!isGenerateUrl(url) || !cfg.enabled) return next.apply(thisArg, args);
  if (input && typeof input === 'object' && typeof input.clone === 'function') {
    return next.apply(thisArg, args);
  }

  var rawBody = init && typeof init.body === 'string' ? init.body : '';
  var plan = null;
  var outArgs = args;
  try {
    plan = planRequest(rawBody, url);
    if (plan.changed.length && plan.body !== rawBody) {
      var newInit = {};
      for (var k in init) newInit[k] = init[k];
      newInit.body = plan.body;
      outArgs = [input, newInit];
    }
    if (plan.model) lastReq = { url: url, raw: rawBody, model: plan.model, base: plan.base || '' };
  } catch (e) { plan = null; }

  var started = nowMs();
  inflight++;

  var p = next.apply(thisArg, outArgs);
  if (!p || typeof p.then !== 'function') { inflight--; return p; }

  return p.then(function (res) {
    inflight--;
    try {
      var ev = newEvidence(plan ? plan.model : '', res.status, 'sse');
      if (res.status === 204) { ev.sawText = true; finish(ev, plan); return res; }
      if (res.status >= 400) { readErrorBody(res, ev); return res; }
      if (cfg.observe && !cfg.safe) startWatcher(ev, plan, started);
      return res;
    } catch (e2) { return res; }
  }, function (err) {
    inflight--;
    try {
      var ev2 = newEvidence(plan ? plan.model : '', 0, 'none');
      ev2.error = String(err && err.message || err || 'fetch failed').slice(0, 80);
      ev2.totalMs = Math.max(1, nowMs() - started);
      finish(ev2, plan);
    } catch (e3) {}
    throw err;
  });
}

/* ---------------- Cài đặt / Khôi phục hook ---------------- */

function installFetchHook() {
  try {
    if (!HOST || typeof HOST.fetch !== 'function') return false;
    if (HOST.fetch.__ar6) return true;
    origFetch = HOST.fetch;
    // fail-open: bất kỳ ngoại lệ nào trong hook đều phải fallback về fetch gốc, tuyệt đối không để request của SillyTavern thất bại
    var wrapped = function (input, init) {
      try { return handleFetch(origFetch, this, arguments); }
      catch (err) {
        try { HOST.console && HOST.console.warn('[AR6] hook error, fallback', err); } catch (e1) {}
        return origFetch.apply(this, arguments);
      }
    };
    wrapped.__ar6 = true;
    HOST.fetch = wrapped;
    hooked = true;
    return true;
  } catch (e) { return false; }
}

function unhookFetch() {
  try {
    if (origFetch && HOOK_TARGET.fetch === HOST.fetch) HOST.fetch = origFetch;
    HOOK_TARGET.fetch = null;
    hooked = false;
  } catch (e) {}
}

var HOOK_TARGET = { fetch: null, xhr: null };

function ensureHooks() {
  if (cfg.safe) { unhookFetch(); unhookXhr(); renderStatus(); return false; }
  var ok = installFetchHook();
  if (ok && HOST.fetch.__ar6) HOOK_TARGET.fetch = HOST.fetch;
  if (cfg.xhr) installXhrHook(); else unhookXhr();
  renderStatus();
  return ok;
}

function installXhrHook() {
  try {
    var X = HOST.XMLHttpRequest;
    if (!X || !X.prototype) return false;
    if (X.prototype.send && X.prototype.send.__ar6) return true;
    var origOpen = X.prototype.open;
    var origSend = X.prototype.send;
    var wrappedOpen = function (m, u) {
      try { this.__ar6url = String(u || ''); } catch (e) {}
      return origOpen.apply(this, arguments);
    };
    var wrappedSend = function (body) {
      try {
        var u = this.__ar6url || '';
        if (isGenerateUrl(u) && cfg.enabled && typeof body === 'string' && body.trim().charAt(0) === '{') {
          var plan = planRequest(body, u);
          if (plan.changed.length && plan.body !== body) { body = plan.body; }
          this.__ar6plan = plan;
        }
      } catch (e) {}
      return origSend.call(this, body);
    };
    wrappedOpen.__ar6 = true;
    wrappedSend.__ar6 = true;
    wrappedSend.__ar6orig = origSend;
    wrappedOpen.__ar6orig = origOpen;
    X.prototype.open = wrappedOpen;
    X.prototype.send = wrappedSend;
    HOOK_TARGET.xhr = { X: X, origOpen: origOpen, origSend: origSend };
    return true;
  } catch (e) { return false; }
}

function unhookXhr() {
  try {
    var rec = HOOK_TARGET.xhr;
    if (!rec) return;
    if (rec.X.prototype.open.__ar6) rec.X.prototype.open = rec.origOpen;
    if (rec.X.prototype.send.__ar6) rec.X.prototype.send = rec.origSend;
    HOOK_TARGET.xhr = null;
  } catch (e) {}
}

/* ---------------- Probe ---------------- */

function httpJson(url, opts, timeoutMs) {
  var f = origFetch || HOST.fetch;
  return new Promise(function (resolve, reject) {
    var done = false;
    var timer = setTimeout(function () {
      if (!done) { done = true; reject(new Error('timeout')); }
    }, timeoutMs || 20000);
    try {
      f(url, opts).then(function (res) {
        return res.text().then(function (t) {
          if (done) return;
          done = true; clearTimeout(timer);
          resolve({ status: res.status, text: t });
        });
      }).catch(function (e) {
        if (done) return;
        done = true; clearTimeout(timer);
        reject(e);
      });
    } catch (e) {
      if (!done) { done = true; clearTimeout(timer); reject(e); }
    }
  });
}

function stripApiSuffix(b) {
  return String(b || '').replace(/\/+$/, '')
    .replace(/\/(?:chat\/completions|completions|messages)$/, '')
    .replace(/\/v1beta\d*$/, '')
    .replace(/\/v1$/, '');
}

function openAIUrl(base) {
  var b = String(base || '').replace(/\/chat\/completions\/?$/, '').replace(/\/+$/, '');
  if (!b) return '';
  return b + '/chat/completions';
}

function nativeUrl(base, model) {
  var m = String(model || '').replace(/:streamGenerateContent$/, '').replace(/:generateContent$/, '');
  return stripApiSuffix(base) + '/v1beta/models/' + encodeURIComponent(m) + ':generateContent';
}

var probeBusy = false;

function runNativeProbe() {
  if (probeBusy) return;
  var base = cfg.dualBase || (lastReq && lastReq.base) || '';
  var key = cfg.dualKey || '';
  var model = (lastReq && lastReq.model) || '';
  if (!base || !model) { banner('⚪ Probe cần gửi trước một lượt chat, hoặc điền Base trên bảng điều khiển', 'gray'); return; }
  probeBusy = true;
  banner('🔬 Đang gửi request Native Probe…', 'gray');
  var body = { contents: [{ role: 'user', parts: [{ text: 'ping' }] }], generationConfig: { maxOutputTokens: 8, temperature: 0 } };
  var headers = { 'content-type': 'application/json' };
  if (key) headers['x-goog-api-key'] = key;
  httpJson(nativeUrl(base, model), { method: 'POST', headers: headers, body: JSON.stringify(body) }, 25000)
    .then(function (r) {
      probeBusy = false;
      if (r.status >= 400 && /invalid|unsupported|400|422/.test(String(r.status))) {
        return httpJson(nativeUrl(base, model), { method: 'POST', headers: headers, body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text: 'ping' }] }] }) }, 25000)
          .then(function (r2) { reportNative(r2, model); });
      }
      reportNative(r, model);
    })
    .catch(function (e) {
      probeBusy = false;
      banner('🔴 Native Probe thất bại: ' + String(e && e.message || e).slice(0, 60), 'bad');
    });
}

function reportNative(r, model) {
  var mv = '';
  try {
    var j = JSON.parse(r.text);
    mv = String((j.modelVersion || j.model || '') || '');
  } catch (e) {}
  var vt = mv ? tierOf(mv) : 0;
  var rt = tierOf(model);
  if (!mv) banner('⚪ Endpoint native trả về ' + r.status + ', không có modelVersion (reverse proxy này có thể không hỗ trợ /v1beta)', 'gray');
  else if (rt > 0 && vt > 0 && vt < rt) banner('🔴 Endpoint native xác nhận bị hạ cấp: Yêu cầu T' + rt + ' → Thực tế ' + mv, 'bad');
  else banner('🟢 Endpoint native trả về modelVersion=' + mv, 'ok');
  render();
}

function runDualProbe() {
  if (probeBusy) return;
  var base = openAIUrl(cfg.dualBase);
  var key = cfg.dualKey || '';
  var model = (lastReq && lastReq.model) || '';
  if (!base || !model) { banner('⚪ Fingerprint kênh đôi cần gửi trước một lượt chat, hoặc điền Base trên bảng điều khiển', 'gray'); return; }
  probeBusy = true;
  banner('🔬 Đang gửi request fingerprint kênh đôi…', 'gray');
  var headers = { 'content-type': 'application/json' };
  if (key) headers['authorization'] = 'Bearer ' + key;
  var ghost = model + '-zzz-not-a-real-model';
  function ask(m) {
    return httpJson(base, {
      method: 'POST', headers: headers,
      body: JSON.stringify({ model: m, messages: [{ role: 'user', content: 'hi' }], max_tokens: 8, stream: false })
    }, 25000).then(function (r) { return r.status; }).catch(function () { return 0; });
  }
  Promise.all([ask(model), ask(ghost)]).then(function (codes) {
    probeBusy = false;
    var real = codes[0], g = codes[1];
    if (!real || real >= 400) banner('🔴 Request tên thật thất bại (HTTP ' + real + '), đường truyền không khả dụng', 'bad');
    else if (!g || g >= 400) banner('🟢 Chế độ nghiêm ngặt: Tên ma bị từ chối (HTTP ' + g + ') ⇒ Gateway định tuyến theo tên, trường model đáng tin cậy', 'ok');
    else banner('🟠 Chế độ nới lỏng: Tên ma cũng trả về 200 ⇒ Gateway không kiểm tra model, trường model trả về không đáng tin cậy', 'warn');
    render();
  });
}

