      '<div class="ar6-c bad"><div class="n">' + c.diff + '</div><div class="l">Bị tráo</div></div>' +
      '<div class="ar6-c warn"><div class="n">' + c.thin + '</div><div class="l">Không suy nghĩ</div></div>' +
      '<div class="ar6-c ok"><div class="n">' + c.same + '</div><div class="l">Khớp</div></div>' +
      '<div class="ar6-c"><div class="n">' + c.unknown + '</div><div class="l">Chưa xác định</div></div>' +
      '</div>';

    html += '<div class="ar6-sec">Phòng vệ</div><div class="ar6-row">' +
      chip(cfg.enabled ? '● Đã bật' : '○ Đã tắt', cfg.enabled) +
      chip('🪶 Vi nhiễu:' + profileLabel(), cfg.refract !== 'off') +
      chip('🧠 Suy nghĩ:' + (cfg.think === 'high' ? 'Cao' : 'Không đổi'), cfg.think === 'high') +
      chip('📌 Khóa tham số:' + (cfg.pin ? 'Bật' : 'Tắt'), cfg.pin) +
      chip('👁 Trình quan sát:' + (cfg.observe ? 'Bật' : 'Tắt'), cfg.observe) +
      chip(cfg.safe ? '🩺 An toàn: Bật' : '🩺 An toàn: Tắt', cfg.safe) +
      '</div>';

    html += '<div class="ar6-sec">Kiểm tra sức khỏe</div><div class="ar6-row">' +
      '<button class="ar6-b" data-ar6="native">🔬 Native Probe</button>' +
      '<button class="ar6-b" data-ar6="dual">🧪 Kênh đôi</button>' +
      '<button class="ar6-b" data-ar6="self">🩺 Tự kiểm tra 20 mục</button>' +
      '<button class="ar6-b" data-ar6="copy">📋 Request gần nhất</button>' +
      '<button class="ar6-b danger" data-ar6="clear">🧹 Xóa sạch</button>' +
      '</div>';

    html += '<div class="ar6-input">' +
      '<input data-ar6="base" placeholder="Reverse proxy Base (vd: https://x/v1)" value="' + esc(cfg.dualBase) + '">' +
      '<input data-ar6="key" placeholder="API Key (có thể để trống)" value="' + esc(cfg.dualKey) + '">' +
      '<button class="ar6-b" data-ar6="save">Lưu</button>' +
      '</div>';

    if (selfTestResult) html += renderSelfTest(selfTestResult);

    html += '<div class="ar6-tbl">' + renderTable(log) + '</div>';

    html += '<div class="ar6-foot"><span>Hook <b class="' + (hooked ? 'ok' : 'bad') + '">' + (hooked ? 'Có' : 'Không') + '</b></span>' +
      '<span>XHR <b class="' + (HOOK_TARGET.xhr ? 'ok' : 'gray') + '">' + (HOOK_TARGET.xhr ? 'Có' : 'Tắt') + '</b></span>' +
      '<span class="ar6-sp"></span><span>Host ' + ((HOST === HOST.top) ? 'top' : 'iframe') + '</span>' +
      '<span>Style <b class="' + (DOC.getElementById(STYLE_ID) ? 'ok' : 'bad') + '">' + (DOC.getElementById(STYLE_ID) ? '✓' : '✗') + '</b></span>' +
      '<span>Click <b class="mono">' + clickCount + '</b></span>' +
      '<span>Nút <b class="' + (bound ? 'ok' : 'bad') + '">' + (bound ? 'Đã gắn' : 'Chưa gắn') + '</b></span>' +
      '<span>Lưu giữ ' + readLog().length + '/' + (cfg.keep || MAX_LOG) + '</span></div>';

    html += '</div>';
  }

  r.innerHTML = html;
  /* Dự phòng định vị inline: Một số container/CSP có thể làm mất tác dụng của style, tại đây thiết lập lại các thuộc tính quan trọng */
  var panelEl = r.firstChild;
  try {
    if (panelEl && panelEl.className && panelEl.className.indexOf('ar6-pill') >= 0) {
      panelEl.style.cursor = 'pointer';
    }
  } catch (e) {}

  if (mode === 'mobile' && !minimized && panelEl) installFloatDrag(panelEl, r);

  if (!r.__ar6bound) {
    r.__ar6bound = true;
    /* Chỉ dùng gắn trực tiếp từng phần tử (bindDirect bên dưới), tránh việc ủy quyền và gắn trực tiếp cùng một cử chỉ kích hoạt 2 lần */
    r.addEventListener('input', onPanelInput);
  }
  bindDirect(r);
  setTimeout(verifyVisible, 400);
  return true;
}

/* Gắn trực tiếp từng nút bấm: Một số extension có thể chặn bubbling hoặc nuốt sự kiện click khiến ủy quyền bị mất tác dụng */
function bindDirect(r) {
  try {
    var nodes = r.querySelectorAll('[data-ar6]');
    for (var i = 0; i < nodes.length; i++) {
      (function (n) {
        if (n.__ar6direct) return;
        var tag = (n.tagName || '').toUpperCase();
        if (tag === 'INPUT') return;          /* Ô nhập liệu xử lý qua sự kiện input */
        n.__ar6direct = true;
        var pdAt = 0;
        var fire = function (ev) {
          if (ev && ev.type === 'pointerdown') {
            pdAt = Date.now();
          } else if (pdAt && Date.now() - pdAt < 900) {
            return;                            /* pointerdown đã xử lý, bỏ qua sự kiện click theo sau */
          }
          try {
            onPanelClick({ target: n, type: (ev && ev.type) || 'click',
              preventDefault: function () {}, stopPropagation: function () {} });
          } catch (e) {}
        };
        n.addEventListener('pointerdown', fire, true);
        n.addEventListener('click', fire, true);
      })(nodes[i]);
    }
  } catch (e) {}
}

function verifyVisible() {
  try {
    var el = DOC && DOC.getElementById(ROOT_ID);
    if (!el) return;
    var b = el.getBoundingClientRect();
    if (!b || b.width < 40 || b.height < 20 || b.top < -5000 || b.left < -5000) {
      var mode = uiMode();
      el.setAttribute('style', panelStyle(mode, minimized));
      el.style.zIndex = '2147483000';
      if (el.parentNode !== DOC.body) DOC.body.appendChild(el);
      if (HOST.console) HOST.console.warn('[AR6] Vị trí bảng điều khiển bất thường, đã cưỡng chế reset');
    }
  } catch (e) {}
}

function profileLabel() {
  if (cfg.refract === 'light') return 'Nhẹ';
  if (cfg.refract === 'mid') return 'Vừa';
  return 'Tắt';
}

function stateOfRun() {
  var s = { kind: 'gray', short: 'Chờ lệnh', line: 'Đang chờ lượt tạo đầu tiên…' };
  if (!cfg.enabled) { s.kind = 'gray'; s.short = 'Đã tắt'; s.line = 'Phòng vệ đã tắt (request được truyền qua nguyên vẹn)'; return s; }
  s.kind = 'ok'; s.short = 'Đang phòng vệ';
  s.line = '<b>Phòng vệ bật</b> · Khóa tham số ' + (cfg.pin ? 'Bật' : 'Tắt') + ' · Vi nhiễu ' + profileLabel() +
    ' · Suy nghĩ ' + (cfg.think === 'high' ? 'Ép buộc cao' : 'Không đổi') + ' · Quan sát ' + (cfg.observe ? 'Bật' : 'Tắt');
  return s;
}

function renderTable(log) {
  if (!log || !log.length) return '<div class="ar6-empty">Chưa có bản ghi nào. Sau khi gửi một lượt hội thoại, nơi này sẽ hiển thị: Model yêu cầu / Model upstream / Phán đoán / Ký tự đầu / Số ký tự / Suy nghĩ.</div>';
  var rows = log.slice(0, 14).map(function (r) {
    var kc = r.code === 'same' ? 'ok' : (r.code === 'diff' || r.code === 'empty' || r.code === 'blocked' || r.code === 'gate' || r.code === 'error' ? 'bad' : (r.code === 'thin' || r.code === 'quota' ? 'warn' : 'gray'));
    var tr = (r.ttft ? (r.ttft / 1000).toFixed(1) + 's' : '—');
    return '<tr>' +
      '<td>' + hhmm(r.at) + '</td>' +
      '<td class="ar6-mono">' + esc(r.req || '—') + '</td>' +
      '<td class="ar6-mono">' + esc(r.obs || '—') + '</td>' +
      '<td><span class="ar6-tag ' + kc + '">' + esc(r.verdict || '') + '</span></td>' +
      '<td>' + tr + '</td>' +
      '<td>' + (r.chars || 0) + '</td>' +
      '<td>' + (r.think ? '✓' : '—') + '</td>' +
      '<td>' + (r.edits ? '+' + r.edits : '—') + '</td>' +
      '</tr>';
  }).join('');
  return '<table class="ar6-t"><thead><tr><th>Thời gian</th><th>Yêu cầu</th><th>Upstream</th><th>Phán đoán</th><th>Ký tự đầu</th><th>Ký tự</th><th>Suy nghĩ</th><th>Thay đổi</th></tr></thead><tbody>' + rows + '</tbody></table>';
}

function renderSelfTest(res) {
  if (!res || !res.items) return '';
  var pass = res.items.filter(function (i) { return i.ok; }).length;
  var rows = res.items.map(function (i) {
    return '<div style="font-size:11px;padding:1px 0"><span style="display:inline-block;width:14px;color:' + (i.ok ? '#1a7f37' : '#cf222e') + '">' + (i.ok ? '✓' : '✗') + '</span>' + esc(i.name) + (i.ok ? '' : ' <span style="color:#a40e26">— ' + esc(i.err || '') + '</span>') + '</div>';
  }).join('');
  return '<div class="ar6-sec">Tự kiểm tra ' + pass + '/' + res.items.length + ' <button class="ar6-b" data-ar6="selftoggle" style="padding:0 6px;font-size:10px">Thu gọn</button></div>' +
    '<div style="padding:2px 12px 8px;max-height:150px;overflow:auto" id="ar6-selftest">' + rows + '</div>';
}

/* ---------------- Sự kiện ---------------- */

function onPanelClick(e) {
  clickCount++;
  var t = e.target;
  while (t && t !== DOC.body && !(t.getAttribute && t.getAttribute('data-ar6'))) t = t.parentNode;
  if (!t || !t.getAttribute) return;
  var act = t.getAttribute('data-ar6');
  if (!act) return;

  if (act === 'expand') { minimized = false; cfg.mx = null; cfg.my = null; syncMin(); render(); return; }
  if (act === 'min') { minimized = true; cfg.mx = null; cfg.my = null; syncMin(); render(); return; }
  if (act === 'hide') {
    /* Tuyệt đối không dùng display:none - Thu nhỏ thành quả cầu nhỏ, luôn có thể bấm vào để khôi phục */
    minimized = true; syncMin(); render();
    banner('Đã thu gọn thành quả cầu nhỏ ở góc dưới bên phải, nhấp vào để khôi phục', 'gray');
    return;
  }

  if (act === '🩺 An toàn: Bật' || act === '🩺 An toàn: Tắt' || act === '🩺 安全:开' || act === '🩺 安全:关') {
    cfg.safe = !cfg.safe;
    saveCfg();
    ensureHooks();
    banner(cfg.safe ? '🩺 Chế độ an toàn: Đã dừng hook (chỉ giữ lại bảng điều khiển)' : '🛡️ Đã khôi phục hook', cfg.safe ? 'warn' : 'ok');
    render();
    return;
  }
  if ((act && (act.indexOf('● Đã bật') >= 0 || act.indexOf('● 已开启') >= 0)) || act === '● Đã bật' || act === '○ Đã tắt' || act === '● 已开启' || act === '○ 已关闭') {
    cfg.enabled = !cfg.enabled; saveCfg(); render();
    banner(cfg.enabled ? '🛡️ Phòng vệ đã bật' : '⚪ Phòng vệ đã tắt', cfg.enabled ? 'ok' : 'gray');
    return;
  }
  if (act.indexOf('🪶 Vi nhiễu') === 0 || act.indexOf('🪶 微扰') === 0) {
    cfg.refract = cfg.refract === 'off' ? 'light' : (cfg.refract === 'light' ? 'mid' : 'off');
    saveCfg(); render();
    banner('🪶 Mức vi nhiễu: ' + profileLabel(), cfg.refract === 'off' ? 'gray' : 'ok');
    return;
  }
  if (act.indexOf('🧠 Suy nghĩ') === 0 || act.indexOf('🧠 思考') === 0) {
    cfg.think = cfg.think === 'high' ? 'off' : 'high'; saveCfg(); render();
    banner(cfg.think === 'high' ? '🧠 Chỉ bù reasoning_effort=high khi thiếu trường' : '🧠 Mức suy nghĩ để preset quyết định', 'gray');
    return;
  }
  if (act.indexOf('📌 Khóa tham số') === 0 || act.indexOf('📌 钉参数') === 0) {
    cfg.pin = !cfg.pin; saveCfg(); render();
    banner('📌 Khóa tham số ' + (cfg.pin ? 'Bật' : 'Tắt'), cfg.pin ? 'ok' : 'gray');
    return;
  }
  if (act.indexOf('👁 Trình quan sát') === 0 || act.indexOf('👁 观察器') === 0) {
    cfg.observe = !cfg.observe; saveCfg(); render();
    banner('👁 Trình quan sát zero-lock ' + (cfg.observe ? 'Bật' : 'Tắt'), cfg.observe ? 'ok' : 'gray');
    return;
  }

  if (act === 'native') { runNativeProbe(); return; }
  if (act === 'dual') { runDualProbe(); return; }
  if (act === 'self') { runSelfTestUI(); return; }
  if (act === 'clear') { try { HOST.localStorage.removeItem(LOG_KEY); } catch (e) {} selfTestResult = null; render(); return; }
  if (act === 'save') {
    var b = DOC.querySelector('[data-ar6="base"]');
    var k = DOC.querySelector('[data-ar6="key"]');
    if (b) cfg.dualBase = String(b.value || '').trim();
    if (k) cfg.dualKey = String(k.value || '').trim();
    saveCfg();
    banner('💾 Đã lưu Base/Key', 'ok');
    return;
  }
  if (act === 'copy') {
    var lr = lastReq;
    var txt = lr ? ('model=' + lr.model + '\nbase=' + lr.base + '\n\n' + String(lr.raw || '').slice(0, 4000)) : '(Chưa bắt được request nào)';
    try {
      if (HOST.navigator && HOST.navigator.clipboard) HOST.navigator.clipboard.writeText(txt);
      banner('📋 Đã sao chép request gần nhất (4000 ký tự đầu)', 'ok');
    } catch (e) { banner('📋 Sao chép thất bại, đã in ra console', 'warn'); try { HOST.console.log(txt); } catch (e2) {} }
    return;
  }
  if (act === 'selftoggle') {
    var box = DOC.getElementById('ar6-selftest');
    if (box) box.style.display = box.style.display === 'none' ? 'block' : 'none';
    return;
  }
}

function onPanelInput(e) {
  var t = e.target;
  if (!t || !t.getAttribute) return;
  var act = t.getAttribute('data-ar6');
  if (act === 'base') cfg.dualBase = String(t.value || '');
  if (act === 'key') cfg.dualKey = String(t.value || '');
  if (act === 'base' || act === 'key') saveCfg();
}

/* ---------------- Điểm kết xuất UI ---------------- */

function installFloatDrag(el, box) {
  try {
    if (!el || !box || el.__ar6drag) return;
    var head = el.querySelector(".ar6-h");
    if (!head) return;
    el.__ar6drag = true;
    head.style.touchAction = "none";
    head.style.cursor = "move";
    var sx = 0, sy = 0, ox = 0, oy = 0, moving = false;
    head.addEventListener("pointerdown", function (e) {
      try {
        if (e.target && e.target.closest && e.target.closest("button")) return;
        var r = box.getBoundingClientRect();
        box.style.left = Math.round(r.left) + "px";
        box.style.top = Math.round(r.top) + "px";
        box.style.right = "auto";
        box.style.bottom = "auto";
        sx = e.clientX; sy = e.clientY; ox = r.left; oy = r.top; moving = true;
        if (head.setPointerCapture) head.setPointerCapture(e.pointerId);
        if (e.preventDefault) e.preventDefault();
      } catch (e1) {}
    }, { passive: false });
    head.addEventListener("pointermove", function (e) {
      if (!moving) return;
      try {
        var w = box.offsetWidth || 300, h = box.offsetHeight || 200;
        var vw = HOST.innerWidth || 360, vh = HOST.innerHeight || 640;
        var nx = Math.max(6, Math.min(vw - w - 6, ox + (e.clientX - sx)));
        var ny = Math.max(6, Math.min(vh - Math.max(h, 60) - 6, oy + (e.clientY - sy)));
        box.style.left = Math.round(nx) + "px";
        box.style.top = Math.round(ny) + "px";
      } catch (e2) {}
    });
    var up = function () {
      if (!moving) return;
      moving = false;
      try {
        var r2 = box.getBoundingClientRect();
        cfg.mx = Math.round(r2.left);
        cfg.my = Math.round(r2.top);
        saveCfg();
      } catch (e3) {}
    };
    head.addEventListener("pointerup", up);
    head.addEventListener("pointercancel", up);
  } catch (e) {}
}

function syncMin() { cfg.min = !!minimized; if (typeof saveCfg === 'function') saveCfg(); }

function render() { try { mountAll(); } catch (e) { try { HOST.console.warn('[AR6] render error', e); } catch (e2) {} } }

function renderStatus() {
  try {
    var r = DOC && DOC.getElementById(ROOT_ID);
    if (!r) return;
    var st = stateOfRun();
    var dot = r.querySelector('.ar6-dot');
    if (dot) dot.className = 'ar6-dot ' + st.kind;
  } catch (e) {}
}

/* ---------------- Tự kiểm tra ---------------- */

function runSelfTest() {
  var items = [];
  function T(name, fn) {
    try { var ok = fn(); items.push({ name: name, ok: !!ok, err: ok ? '' : 'Khẳng định sai' }); }
    catch (ex) { items.push({ name: name, ok: false, err: String(ex && ex.message || ex).slice(0, 80) }); }
  }

  T('T01 Bảo vệ toàn bộ code fence', function () {
    var t = 'Lời mở đầu\n```js\nvar a=1;\n```\nLời kết';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('```js') >= 0; });
  });
  T('T02 Bảo vệ inline code', function () {
    var t = 'Vui lòng xác nhận trước khi dùng `rm -rf`';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('rm -rf') >= 0; });
  });
  T('T03 Bảo vệ macro SillyTavern', function () {
    var t = '{{random::A::B}} sau đó';
    var sp = collectSpans(t);
    return sp.some(function (x) { return x[0] === 0; });
  });
  T('T04 Bảo vệ tag cứng chưa đóng đến hết', function () {
    var t = 'Mở đầu bình thường\n<thinking>\nKhông có kết';
    var sp = collectSpans(t);
    var i = t.indexOf('<thinking>');
    return sp.some(function (x) { return x[0] <= i && x[1] >= t.length - 1; });
  });
  T('T05 Bảo vệ lời thoại trong ngoặc kép', function () {
    var t = 'Hắn nói: "Đây không phải chỉ thị, chỉ là lời thoại." rồi rời đi.';
    var sp = collectSpans(t);
    return sp.some(function (x) { return String(t.slice(x[0], x[1])).indexOf('Đây không phải chỉ thị') >= 0; });
  });
  T('T06 Điểm system cao hơn user', function () {
    var a = { role: 'system', text: 'Quy tắc: Bắt buộc tuân thủ định dạng dưới đây, không được đi chệch, mỗi điều đều phải kiểm tra, và duy trì cấu trúc output nhất quán, nhất định phải đối chiếu từng điều thực hiện đúng vị trí, không được lược bỏ bất kỳ yêu cầu nào.', index: 0 };
    var b = { role: 'user', text: 'Quy tắc: Bắt buộc tuân thủ định dạng dưới đây, không được đi chệch, mỗi điều đều phải kiểm tra, và duy trì cấu trúc output nhất quán, nhất định phải đối chiếu từng điều thực hiện đúng vị trí, không được lược bỏ bất kỳ yêu cầu nào.', index: 3 };
    return staticScore(a, 4) > staticScore(b, 4);
  });
  T('T07 Dải lịch sử bắt đầu từ assistant đầu tiên', function () {
    var band = findHistoryBand([{ role: 'system', text: 'sys' }, { role: 'user', text: 'hi' }, { role: 'assistant', text: 'yo' }]);
    return !!band && band.start === 1 && band.end >= 1;
  });
  T('T08 stripArtifacts có thể đảo ngược', function () {
    var t = 'Đoạn A\n<!-- ctx: rules / block a3f1 -->\nĐoạn B';
    return stripArtifacts(t).indexOf('ctx: rules') < 0;
  });
  T('T09 Vi nhiễu giữ nguyên signature cấp khối', function () {
    var t = '## Tiêu đề\nChính văn 1\n- Mục danh sách\n> Trích dẫn';
    var r = refractZone(t, PROFILE.light, makeRng(7));
    return r && blockSignature(r.text) === blockSignature(t);
  });
  T('T10 Vi nhiễu chạy lần hai ổn định', function () {
    var t = '## Tiêu đề\nChính văn 1\n- Mục danh sách';
    var r1 = refractZone(t, PROFILE.light, makeRng(3));
    var r2 = refractZone(r1.text, PROFILE.light, makeRng(3));
    return r1.text === r2.text;
  });
  T('T11 Không vi nhiễu bên trong code block', function () {
    var t = '```\n## Không phải tiêu đề\n```';
    var r = refractZone(t, PROFILE.mid, makeRng(5));
    return !r.changed || r.text === t;
  });
  T('T12 Khóa tham số xóa bỏ models[]', function () {
    var body = JSON.stringify({ model: 'gemini-4-argon', models: ['a', 'b'], allow_fallbacks: true, messages: [{ role: 'user', content: 'hi' }] });
    var p = planRequest(body, 'https://x/chat-completions/generate');
    var o = JSON.parse(p.body);
    return !('models' in o) && o.allow_fallbacks === false;
  });
  T('T13 Khóa tham số không tạo trường ảo', function () {
    var body = JSON.stringify({ model: 'g', messages: [{ role: 'user', content: 'hi' }] });
    var p = planRequest(body, 'https://x/chat-completions/generate');
    var o = JSON.parse(p.body);
    return !('models' in o) && !('route' in o);
  });
  T('T14 Mức suy nghĩ không ghi đè trường đã có', function () {
    var body = JSON.stringify({ model: 'g', reasoning_effort: 'medium', messages: [{ role: 'user', content: 'hi' }] });
    var p = planRequest(body, 'https://x/chat-completions/generate');
    return JSON.parse(p.body).reasoning_effort === 'medium';
  });
  T('T15 Không viết lại URL không phải generate', function () {
    var body = JSON.stringify({ model: 'g' });
    var p = planRequest(body, 'https://x/api/backends/chat-completions/status');
    return p.changed.length === 0 && p.body === body;
  });
  T('T16 Cùng model phán đoán khớp', function () {
    var ev = newEvidence('gemini-4-argon', 200, 'sse');
    ev.sawText = true; ev.hasThink = true; ev.observed.push('google/gemini-4-argon');
    return verdictOf(ev).code === 'same';
  });
  T('T17 Hạ cấp phán đoán bị tráo', function () {
    var ev = newEvidence('gemini-4-argon', 200, 'sse');
    ev.sawText = true; ev.hasThink = true; ev.observed.push('gemini-3.1-flash-lite');
    return verdictOf(ev).code === 'diff';
  });
  T('T18 4xx không phán đoán bị tráo', function () {
    var ev = newEvidence('gemini-4-argon', 429, 'json');
    ev.sawText = false;
    return verdictOf(ev).code === 'quota';
  });
  T('T19 normModel bóc tách prefix kênh', function () {
    return normModel('pggo-google/gemini-4-argon:generateContent') === 'gemini-4-argon';
  });
  T('T20 estimateTokens xấp xỉ tiếng Trung', function () {
    var n = estimateTokens('一二三四五六七八九十');
    return n >= 7 && n <= 11;
  });

  selfTestResult = { at: Date.now(), items: items };
  return selfTestResult;
}

function runSelfTestUI() {
  var res = runSelfTest();
  var pass = res.items.filter(function (i) { return i.ok; }).length;
  var bad = res.items.filter(function (i) { return !i.ok; });
  banner('🩺 Tự kiểm tra ' + pass + '/' + res.items.length + (bad.length ? (', thất bại: ' + bad[0].name) : ', toàn bộ đã đạt'), bad.length ? 'bad' : 'ok');
  render();
}

/* ---------------- Nút bấm script ---------------- */

function bindScriptButtons() {
  if (bound) return true;
  /* Mấu chốt: SillyTavern Assistant chạy script trong iframe, eventOn/getButtonEvent được inject tại "window của chính script",
     không nằm ở tầng cao nhất; nếu chỉ tìm kiếm HOST/parent/top sẽ hoàn toàn thất bại ⇒ nút trên thanh công cụ sẽ vĩnh viễn không có phản hồi */
  var scope = [];
  function push(w) {
    if (!w) return;
    for (var q = 0; q < scope.length; q++) if (scope[q] === w) return;
    scope.push(w);
  }
  push(SELF_WIN);
  try { push(SELF_WIN && SELF_WIN.parent); } catch (e) {}
  push(HOST);
  try { push(HOST && HOST.parent); } catch (e) {}
  try { push(HOST && HOST.top); } catch (e) {}

  /* Mỗi hành động đăng ký nhiều bí danh: Tên nút trong JSON + Tên kế thừa bản cũ + Tên trần không emoji */
  var ACTIONS = [
    { names: ['🛡️ Tự kiểm tra trạng thái', 'Tự kiểm tra trạng thái', 'Tự kiểm tra', '🛡️ 状态自检', '状态自检', '自检'],
      fn: function () { runSelfTestUI(); } },
    { names: ['🔄 Bật/Tắt phòng vệ', 'Bật/Tắt phòng vệ', 'Bật tắt phòng vệ', '🔄 开/关防护', '开/关防护', '开关防护'],
      fn: function () {
        cfg.enabled = !cfg.enabled; saveCfg(); render();
        banner(cfg.enabled ? '🛡️ Phòng vệ đã bật' : '⚪ Phòng vệ đã tắt', cfg.enabled ? 'ok' : 'gray');
      } },
    { names: ['🪶 Đổi mức vi nhiễu', 'Đổi mức vi nhiễu', '🧪 Bật/Tắt xáo trộn', 'Bật/Tắt xáo trộn', '🪶 切微扰档', '切微扰档', '🧪 开/关混淆', '开/关混淆'],
      fn: function () {
        cfg.refract = cfg.refract === 'off' ? 'light' : (cfg.refract === 'light' ? 'mid' : 'off');
        saveCfg(); render();
        banner('🪶 Mức vi nhiễu: ' + profileLabel(), cfg.refract === 'off' ? 'gray' : 'ok');
      } },
    { names: ['🧹 Xóa bản ghi', 'Xóa bản ghi', '🧹 清空记录', '清空记录'],
      fn: function () { try { HOST.localStorage.removeItem(LOG_KEY); } catch (e) {} selfTestResult = null; render(); banner('🧹 Bản ghi đã được dọn sạch', 'gray'); } }
  ];

  for (var i = 0; i < scope.length; i++) {
    var w = scope[i];
    if (!w) continue;
    var okCount = 0;
    try {
      if (typeof w.eventOn !== 'function' || typeof w.getButtonEvent !== 'function') continue;
      for (var a = 0; a < ACTIONS.length; a++) {
        var act = ACTIONS[a];
        for (var n = 0; n < act.names.length; n++) {
          try {
            var ev = w.getButtonEvent(act.names[n]);
            if (!ev) continue;
            (function (fn) {
              w.eventOn(ev, function () { try { fn(); } catch (e) {} });
            })(act.fn);
            okCount++;
            break;                       /* Hành động này chỉ cần gắn với 1 bí danh là đủ */
          } catch (e) {}
        }
      }
      if (okCount > 0) { bound = true; btnBoundAt = Date.now(); return true; }
    } catch (e) {}
  }
  return false;
}

/* ---------------- Vòng đời ---------------- */

function step(name, fn) {
  try { fn(); }
  catch (e) { try { HOST.console.warn('[AR6] ' + name + ' thất bại: ', e); } catch (e2) {} }
}

function boot() {
  if (booted) { render(); return; }
  booted = true;
  step('Cấu hình', function () { cfg = readCfg(); minimized = !!cfg.min; });
  step('Host', function () { if (!HOST || !DOC) throw new Error('Tài liệu host không khả dụng'); });
  step('Style', function () { ensureStyle(DOC); });
  step('Hook', function () { ensureHooks(); });
  step('Bảng điều khiển', function () { render(); });
  step('Banner', function () {
    var where = (HOST === HOST.top) ? 'Top level' : 'iframe';
    var msg = (hooked ? '🛡️' : '⚠️') + ' Anti-Route v' + VERSION + ' đã sẵn sàng · ' +
      (cfg.enabled ? 'Phòng vệ bật' : 'Phòng vệ tắt') + ' · Host ' + where + (hooked ? '' : ' · Chưa gắn hook');
    banner(msg, hooked ? 'ok' : 'bad');
  });
  step('Nút bấm', function () { bindScriptButtons(); });
  step('Fallback', function () {
    if (bootTimer) clearInterval(bootTimer);
    var tries = 0;
    bootTimer = setInterval(function () {
      tries++;
      try {
        ensureHooks();
        bindScriptButtons();
        if (tries >= 4) { clearInterval(bootTimer); bootTimer = null; }
      } catch (e) {}
    }, 1500);
  });
  try { HOST.console.log(TAG + ' v' + VERSION + ' đã khởi động; chế độ=' + uiMode() + '; hook=' + hooked); } catch (e) {}
}

function dispose() {
  try { if (bootTimer) { clearInterval(bootTimer); bootTimer = null; } } catch (e) {}
  try { if (bannerTimer) { clearTimeout(bannerTimer); bannerTimer = null; } } catch (e) {}
  step('Khôi phục fetch', unhookFetch);
  step('Khôi phục XHR', unhookXhr);
  step('Gỡ bỏ bảng điều khiển', function () {
    var el = DOC && DOC.getElementById(ROOT_ID);
    if (el && el.parentNode) el.parentNode.removeChild(el);
    var bn = DOC && DOC.getElementById('ar6-bn');
    if (bn && bn.parentNode) bn.parentNode.removeChild(bn);
  });
  booted = false; bound = false;
}

try {
  // Mobile khi chuyển tab ngầm / bfcache bị đóng băng không được hủy: triển khai cũ mỗi lần chuyển đều dispose dẫn đến khi quay lại bị "mất tích",
  // hơn nữa thời điểm gỡ bỏ lại vô tình trùng khớp với hành động lưu dữ liệu của SillyTavern.
  HOST.addEventListener('pagehide', function (ev) {
    if (!ev || ev.persisted) return;
    try { if (bannerTimer) { clearTimeout(bannerTimer); bannerTimer = null; } } catch (e1) {}
  });
  HOST.addEventListener('pageshow', function (ev) {
    if (ev && ev.persisted) { try { ensureHooks(); } catch (e2) {} }
  });
} catch (e) {}

boot();


